;;
; @file   script_29.asm
; @brief   Farm event: a boy asks the player for an egg (dialogs $0418-$041B). If the player hands over an egg (carry
;         item $14) he pays 2 and happiness rises, otherwise he leaves disappointed. Started by fAreaEvents_Farm (slot
;         0).
; @bank   $B4   (AI byte code; script id $29, slot table generated by tools/ai/aidata.py from defs/ai/scripts.json)
; @see     script_23 docs/ai/commands.md
;;



    incsrc "../../../../build/gen/ai/slots_29.asm"
 
; Slot 0.
; Entry code: starts 1 child script (slots $01); dialogs $041B, $0418, $0419, $041A.
; Slot index: 0
; Started by: fAreaEvents_Farm (A=$0000)
pAIScripting0x29_Data01:
    %AICMD0x09_StartScript($01, pAIScripting0x29_Data01_Actor01)                                   ;B4C447
    %AICMD0x38_WaitForFadeIn()                                               ;B4C44B
    %AICMD0x10_End()                                           ;B4C44C
; Child script (slot $01) of Data01: actor. Spawns at (104,424).
pAIScripting0x29_Data01_Actor01:
    %AICMD0x15_JumpIfEquals8(nCurrentTimeID, 18, pAIScripting0x29_L008)      ;B4C44D
    %AICMD0x1A_SpawnNpc($0068, $01A8, aAIScriptingData_L055, $02)                     ;B4C454
; Idle until the player presses A at the NPC (AICMD0x2D): jumps to OnInteract, or to OnItemOffered while an item is
; carried.
pAIScripting0x29_Data01_Actor01_WaitInteract:
    %AICMD0x2D_JumpOnInteract(pAIScripting0x29_Data01_Actor01_OnInteract, pAIScripting0x29_Data01_Actor01_OnItemOffered)                               ;B4C45C
    %AICMD0x16_JumpIfBetween8(nCurrentTimeID, 18, 24, pAIScripting0x29_Data01_Actor01_NoEggEvening) ;B4C461
    %AICMD0x12_Jump(pAIScripting0x29_Data01_Actor01_WaitInteract)                                   ;B4C469
; A pressed while carrying an item (strcPlayerData.carryItemIdPrev is tested next).
pAIScripting0x29_Data01_Actor01_OnItemOffered:
    %AICMD0x15_JumpIfEquals8(wram80(strcPlayerData.carryItemIdPrev), 20, pAIScripting0x29_Data01_Actor01_EggReceived)             ;B4C46C
    %AICMD0x1C_ShowDialog($041B, $00)                          ;B4C473
    %AICMD0x12_Jump(pAIScripting0x29_Data01_Actor01_WaitInteract)                                   ;B4C477
; A pressed without a carried item.
pAIScripting0x29_Data01_Actor01_OnInteract:
    %AICMD0x1C_ShowDialog($0418, $00)                          ;B4C47A
    %AICMD0x12_Jump(pAIScripting0x29_Data01_Actor01_WaitInteract)                                   ;B4C47E
; Evening ($12-$18) without an egg: dialog $0419, happiness -5, then leave.
pAIScripting0x29_Data01_Actor01_NoEggEvening:
    %AICMD0x1C_ShowDialog($0419, $00)                          ;B4C481
    %AICMD0x41_AddValue16(nPlayerHappiness, -5)                ;B4C485
    %AICMD0x12_Jump(pAIScripting0x29_Data01_Actor01_Leave)                                   ;B4C48B
; The player handed over an egg (carry item $14): dialog $041A, nMoney +2, happiness +30.
pAIScripting0x29_Data01_Actor01_EggReceived:
    %AICMD0x1C_ShowDialog($041A, $00)                          ;B4C48E
    %AICMD0x42_AddValue24(nMoney, 2)                           ;B4C492
    %AICMD0x41_AddValue16(nPlayerHappiness, 30)                ;B4C499
    %AICMD0x12_Jump(pAIScripting0x29_Data01_Actor01_Leave)                                   ;B4C49F
; Common exit: set event4 bit $0B, clear bit $0A, walk away and remove the object.
pAIScripting0x29_Data01_Actor01_Leave:
    %AICMD0x23_OrWithIndexedValue(strcFlags.event4, $0B)       ;B4C4A2
    %AICMD0x28_ClearBit(strcFlags.event4, $0A)                          ;B4C4A7
    %AICMD0x1B_SetSprite($02B6, $00)                                     ;B4C4AC
    %AICMD0x0D_MoveObject($FF, $00, $60, $01)                             ;B4C4B0
    %AICMD0x37_RemoveObject()                                               ;B4C4B5
    %AICMD0x10_End()                                           ;B4C4B6
pAIScripting0x29_L008:
    %AICMD0x10_End()                                           ;B4C4B7
